});

console.log(await result.stdoutText);
// Now you have rendered HTML that can be sent via email or saved
```

### Demo 6: Real-time code execution and streaming

Process PHP output as it’s generated:

```javascript
const php = new PHP(await loadNodeRuntime('8.3'));

await php.writeFile(
    '/stream-demo.php',
    `<?php
// Simulate long-running process
echo "Starting process...\\n";
flush();

for ($i = 1; $i <= 10; $i++) {
    echo "Processing item $i/10...\\n";
    flush();
    usleep(100000); // Sleep 100ms
}

echo "Process complete!\\n";
?>`
);

// Run PHP script
const streamedResponse = await php.runStream({
    scriptPath: '/stream-demo.php',
});

streamedResponse.stdout.pipeTo(
    new WritableStream({
        write(chunk) {
            console.log(chunk);
        },
    })
);
```

## Integration patterns

### Pattern 1: Express.js middleware

Integrate PHP processing into an Express.js application:

```TypeScript
const app = express();
const php = new PHP(await loadNodeRuntime('8.3'));

// PHP execution middleware
app.use('/php', async (req, res, next) => {
    try {
        const phpScript = req.query.script || 'index.php';
        const result = await php.runStream({
            scriptPath: `/www/${phpScript}`,
            env: {
                REQUEST_METHOD: req.method,
                QUERY_STRING: new URLSearchParams(
                    req.query as Record<string, string>
                ).toString(),
                REQUEST_URI: req.url,
            },
        });

        res.send(await result.stdoutText);
    } catch (error) {
        next(error);
    }
});

app.listen(3000, () => {
    console.log('Server with PHP support running on port 3000');
});
```

### Pattern 2: Automated testing

Create automated tests for PHP code:

```TypeScript
describe('PHP Functions', () => {
    let php: PHP;

    beforeAll(async () => {
        php = new PHP(await loadNodeRuntime('8.3'));
    });

    it('should calculate sum correctly', async () => {
        const result = await php.run({
            code: `<?php
        function sum($a, $b) {
          return $a + $b;
        }
        echo sum(5, 3);
      ?>`,
        });

        expect(result.text).toBe('8');
    });

    it('should handle JSON operations', async () => {
        const input = { name: 'Test', value: 42 };
        const result = await php.run({
            code: `<?php
        $input = json_decode('${JSON.stringify(input)}', true);
        $output = [
          'received' => $input,
          'doubled' => $input['value'] * 2
        ];
        echo json_encode($output);
      ?>`,
        });

        const output = JSON.parse(result.text);
        expect(output.doubled).toBe(84);
    });
});
```

### Pattern 3: Build tool integration

Use in build scripts with other Node.js tools:

```javascript
async function generateDocumentation() {
    const php = new PHP(await loadNodeRuntime('8.3'));

    // Create output directory
    php.mkdir('/output');

    // Generate documentation
    const result = await php.runStream({
        code: `<?php
echo "Generating documentation...\\n";

$summary = "# Generated Documentation\\n\\n";
$summary .= "Generated at: " . date('Y-m-d H:i:s') . "\\n\\n";

file_put_contents('/output/summary.md', $summary);
echo "Documentation generated successfully!\\n";
?>`,
    });

    console.log(await result.stdoutText);

    // Extract generated docs back to Node.js file system
    await fs.mkdir('./docs', { recursive: true });
    const summaryContent = await php.readFileAsText('/output/summary.md');
    await fs.writeFile('./docs/summary.md', summaryContent);

    console.log('Documentation saved to ./docs/summary.md');
}

generateDocumentation().catch(console.error);
```

## Advanced features

### Working with environment variables

```javascript
const php = new PHP(await loadNodeRuntime('8.3'));

const result = await php.runStream({
    code: '<?php echo getenv("CUSTOM_VAR"); ?>',
    env: {
        CUSTOM_VAR: 'Hello from Node.js!',
    },
});

console.log(await result.stdoutText);
```

### Error handling

```javascript
const php = new PHP(await loadNodeRuntime('8.3'));

try {
    const result = await php.runStream({
        code: '<?php trigger_error("Test error", E_USER_ERROR); ?>',
    });

    const stdout = await result.stdoutText;
    const stderr = await result.stderrText;

    console.log('stdout:', stdout);
    console.log('stderr:', stderr);

    if (stderr) {
        console.error('PHP produced errors:', stderr);
    }
} catch (error: any) {
    console.error('JavaScript Error:', error.message);
}
```

## Performance considerations

-   **Reuse PHP instances**: Creating a new PHP instance is expensive. Reuse the same instance when possible.
-   **Batch operations**: Group multiple file operations together rather than running separate scripts.
-   **Memory management**: Large files may impact performance. Consider streaming for big datasets.
-   **Caching**: Cache compiled PHP scripts and frequently accessed data.

WordPress Playground was created as a programmable tool. Below you’ll find a few examples of what you can do with it. Each discussed API is described in detail in the [APIs section](https://developer.wordpress.org/playground/developers/apis/):

## Embed WordPress on your website

Playground can be embedded on your website using the HTML `<iframe>` tag as follows:

```html
<iframe src="https://playground.wordpress.net/"></iframe>
```

Every visitor will get their own private WordPress instance for free. You can then customize it using one of the [Playground APIs](https://developer.wordpress.org/playground/developers/apis/).

**Careful with the demo site**

The site at [https://playground.wordpress.net](https://playground.wordpress.net) is there to support the community, but there are no guarantees it will continue to work if the traffic grows significantly.

If you need certain availability, you should [host your own WordPress Playground](https://developer.wordpress.org/playground/developers/architecture/host-your-own-playground).

## Control the embedded website

WordPress Playground provides three APIs you can use to control the iframed website. All the examples in this section are built using one of these:

-   [Query API](https://developer.wordpress.org/playground/developers/apis/query-api) enable basic operations using only query parameters
-   [Blueprints API](https://developer.wordpress.org/playground/blueprints) give you a great degree of control with a simple JSON file
-   [JavaScript API](https://developer.wordpress.org/playground/developers/apis/javascript-api) gives you full control via a JavaScript client loaded from `playground.wordpress.net` or installed from npm

Learn more about each of these APIs in the [APIs overview section](https://developer.wordpress.org/playground/developers/apis/).

## Showcase a plugin or theme from WordPress directory

You can install plugins and themes from the WordPress directory with only URL parameters. This iframe preinstalls the `coblocks` and `friends` plugins and the `pendant` theme.  
This is called [Query API](https://developer.wordpress.org/playground/developers/apis/query-api/) and you can learn more about it [here](https://developer.wordpress.org/playground/developers/apis/query-api/).

```html
<iframe src="https://playground.wordpress.net/?plugin=coblocks"></iframe>
```

## Showcase any plugin or theme

What if your plugin is not in the WordPress directory?

You can still showcase it on Playground by using [JSON Blueprints](https://developer.wordpress.org/playground/blueprints). For example, this Blueprint would download and install a plugin and a theme from your website and also import some starter content:

```json
{
    "steps": [
        {
            "step": "installPlugin",
            "pluginData": {
                "resource": "url",
                "url": "https://your-site.com/your-plugin.zip"
            }
        },
        {
            "step": "installTheme",
            "themeData": {
                "resource": "url",
                "url": "https://your-site.com/your-theme.zip"
            }
        },
        {
            "step": "importWxr",
            "file": {
                "resource": "url",
                "url": "https://your-site.com/starter-content.wxr"
            }
        }
    ]
}
```

See [getting started with Blueprints](https://developer.wordpress.org/playground/blueprints/getting-started) to learn more.

## Preview pull requests from your repository

You can preview repository code two ways: directly with `git:directory`, or by pointing to a `.zip` from your CI pipeline. Here’s the `git:directory` approach using [Blueprints](https://developer.wordpress.org/playground/blueprints):

```json
{
    "steps": [
        {
            "step": "installPlugin",
            "pluginData": {
                "resource": "git:directory",
                "url": "https://github.com/my-user/my-repo",
                "ref": "refs/pull/1/head",
                "refType": "refname"
            },
            "options": {
                "activate": true
            },
            "progress": {
                "caption": "Installing plugin from my-user/my-repo PR #1"
            }
        }
    ]
}
```

In the code above, it will install a plugin from a repository located at the `url`, and the reference to find the branch is `refType`; in this case, it will use `refname`, but it can also use `branch`, `tag`, and `commit`.

You can automate this process using the [GitHub Action to generate preview links](https://developer.wordpress.org/playground/guides/github-action-pr-preview), which will help streamline the process.

Loading a `.zip` file is another alternative for previewing your project. See the [live example of Gutenberg PR previewer](https://playground.wordpress.net/gutenberg.html).

To use Playground as a PR previewer, you need:

-   A CI pipeline that bundles your plugin or theme
-   Public access to the generated `.zip` file

Those zip bundles aren’t any different from regular WordPress Plugins, which means you can install them in Playground using the [JSON Blueprints](https://developer.wordpress.org/playground/blueprints) API. Once you expose an endpoint like https://your-site.com/pull-request-1234.zip, the following Blueprint will do the rest:

```json
{
    "steps": [
        {
            "step": "installPlugin",
            "pluginData": {
                "resource": "url",
                "url": "https://your-site.com/pull-request-1234.zip"
            }
        }
    ]
}
```

The official Playground demo uses this technique to preview pull requests from the Gutenberg repository:

```json
{
    "landingPage": "/wp-admin/plugins.php?test=42test",
    "steps": [
        {
            "step": "login",
            "username": "admin",
            "password": "password"
        },
        {
            "step": "writeFile",
            "path": "/tmp/gutenberg.zip",
            "data": {
                "resource": "url",
                "url": "/plugin-proxy.php?org=WordPress&repo=gutenberg&workflow=Build%20Gutenberg%20Plugin%20Zip&artifact=gutenberg.zip&pr=60819",
                "caption": "Downloading Gutenberg PR 60819"
            },
            "progress": {
                "weight": 2,
                "caption": "Applying Gutenberg PR 60819"
            }
        },
        {
            "step": "installPlugin",
            "pluginData": {
                "resource": "vfs",
                "path": "/tmp/gutenberg.zip"
            }
        }
    ]
}
```

[Try it out!](https://playground.wordpress.net/?mode=seamless#)

### Preview WordPress Core and Gutenberg Branches or PRs

You can preview specific pull requests from WordPress Core and Gutenberg repositories using Query API parameters. Gutenberg branches also have an alternative to preview them with the parameter `gutenberg-branch`. This is useful for testing the latest trunk changes or specific feature branches without creating a PR.

-   Preview a specific WordPress Core PR: \`https://playground.wordpress.net/?core-pr=9500\`
-   Preview a specific Gutenberg PR: \`https://playground.wordpress.net/?gutenberg-pr=73010\`
-   Preview the Gutenberg trunk branch: \`https://playground.wordpress.net/?gutenberg-branch=trunk\`

## Build a compatibility testing environment

Test your plugin across PHP and WordPress versions by configuring them in Playground. This helps you verify compatibility before release.

With the Query API, you’d simply add the `php` and `wp` query parameters to the URL:

```html
<iframe src="https://playground.wordpress.net/?php=8.3&wp=6.1"></iframe>
```

With JSON Blueprints, you’d use the `preferredVersions` property:

```json
{
    "preferredVersions": {
        "php": "8.3",
        "wp": "6.1"
    }
}
```

## Run PHP code in the browser

The JavaScript API provides the `run()` method which you can use to run PHP code in the browser. This example loads the client directly from `playground.wordpress.net`, so no npm installation or build step is required. See the [JavaScript API quick start](https://developer.wordpress.org/playground/developers/apis/javascript-api#quick-start) for setup instructions and the npm alternative.

```html
<iframe id="wp"></iframe>
<script type="module">
    const { startPlaygroundWeb } = await import('https://playground.wordpress.net/client/index.js');

    const client = await startPlaygroundWeb({
        iframe: document.getElementById('wp'),
        remoteUrl: 'https://playground.wordpress.net/remote.html',
    });
    await client.isReady();
    await client.run({
        code: `<?php
        require("/wordpress/wp-load.php");

        update_option("blogname", "Playground is really cool!");
        echo "Site title updated!";
        `,
    });
    await client.goTo('/');
</script>
```

Combine that with a code editor like Monaco or CodeMirror, and you’ll get live code snippets like in [this article](https://adamadam.blog/2023/02/16/how-to-modify-html-in-a-php-wordpress-plugin-using-the-new-tag-processor-api/)!

